// FieldTypes is the backend's full list of column types, lifted from
// components.schemas.FieldType.enum. oapi-codegen runs with skip-prune: false
// and no operation $refs the enum's constants, so client.gen.go declares a bare
// `type FieldType string` and nothing there can tell a valid column type from a
// typo. `apply -f <TableSchema>` validates spec.fields.<name>.type against this
// list client-side, which is what turns a 422 with an object-shaped body into a
// plain exit 2 naming the valid values.
var FieldTypes = []string{
	"String",
	"Text",
	"UUID",
	"SmallInteger",
	"Integer",
	"BigInteger",
	"Decimal",
	"Float",
	"DateTime",
	"Date",
	"Boolean",
	"Array",
	"BigIntArray",
	"IntArray",
	"UUIDArray",
	"Json",
	"Jsonb",
	"Bytea",
	"Varbit",
	"SmallIntArray",
}
